// The light of one part (stopped, starting, running, problem, or none for a
// part with nothing to start or check) and what a screen shows of it. Plain
// data and the rules for changing it; the launcher decides when.
export function newPartLight(part) {
    return {
        light: part.run || part.health ? "stopped" : "none",
        step: null,
        problem: null,
        outside: false,
        program: null,
        stopping: false,
        starting: null,
    };
}
export function setLight(inner, light, step) {
    inner.light = light;
    inner.step = step;
    if (light !== "problem")
        inner.problem = null;
}
export function failLight(inner, problem) {
    inner.problem = { details: [], ...problem };
    inner.light = "problem";
    inner.step = null;
}
export function resetLight(inner) {
    inner.light = "stopped";
    inner.step = null;
    inner.problem = null;
    inner.outside = false;
}
export function viewOf(part, inner, link) {
    return {
        id: part.id,
        name: part.name,
        area: part.area,
        does: part.does,
        dependsOn: part.dependsOn,
        start: part.start,
        light: inner.light,
        step: inner.step,
        problem: inner.problem,
        link,
        // A part that starts with others has no buttons, but can be tried
        // again after a problem.
        canStart: part.start !== "never" &&
            Boolean(part.run) &&
            (inner.light === "problem" ||
                (inner.light === "stopped" && part.start !== "with")),
        canStop: part.start !== "with" &&
            !inner.outside &&
            Boolean(inner.program || inner.starting),
        outside: inner.outside,
    };
}
